mapper.update:
update pet
type_id = #{typeId}, name = #{name}, gender = #{gender}, img = #{img}, price = #{price}, store = #{store}, introduce = #{introduce}, content = #{content}, sale_status = #{saleStatus}, recommend = #{recommend},
where id = #{id}

update pet
set store = store - 1
where id = #{id}

update pet
set store = store + 1
where id = #{id}

mapper.select:
select p.id, p.name, p.gender, p.img, p.price, p.store, p.introduce, p.content,
p.sale_status, p.recommend,pt.name as typeName,ps.nickname as shopName
from pet p
left join pet_type pt on p.type_id = pt.id
left join pet_shop ps on p.shop_id = ps.id

    and p.name like concat('%',#{name},'%')
    and ps.nickname like concat('%',#{shopName},'%')
    and p.type_id = #{typeId}
    and p.sale_status = #{saleStatus}
    and p.recommend = #{recommend}
    and p.shop_id = #{shopId}

order by p.id desc

select count(*)
from pet
where sale_status = #{saleStatus}

select id, name, gender, img, price, store, sale_status from pet

    and name like concat('%',#{name},'%')
    and type_id = #{typeId}
    and store > 0
    and price between #{priceMin} and #{priceMax}
    and shop_id = #{shopId}

order by recommend desc, id desc

select id
from pet
where shop_id = #{shopId}
